import Foundation
import HegemonCore
import SwiftUI

/// The painted board, traced from Josh's photo: territory outlines, rivers and peaks in the
/// photo's pixel space (generated by tools/board_shapes.py).
struct BoardArt: Decodable {
    struct Shape: Decodable {
        let polygon: [[Double]]
        let label: [Double]
        /// Lettering angle on the board, in degrees clockwise.
        let angle: Double
        /// Where the army token sits.
        let token: [Double]
    }

    let size: [Double]
    let territories: [TerritoryID: Shape]
    let seas: [SeaZoneID: [Double]]
    let rivers: [[[Double]]]
    let peaks: [TerritoryID: [[Double]]]

    static let shared: BoardArt = {
        let url = Bundle.main.url(forResource: "map_shapes", withExtension: "json")!
        return try! JSONDecoder().decode(BoardArt.self, from: Data(contentsOf: url))
    }()

    /// The painted part of the photo (both halves of the board).
    static let frame = CGRect(x: 100, y: 5, width: 1805, height: 915)
    /// Where the two halves of the board meet.
    static let seamX: CGFloat = 1006
}

/// Maps board coordinates into a view, keeping the board's proportions.
struct BoardTransform {
    let scale: CGFloat
    let offset: CGPoint

    init(fitting size: CGSize) {
        let f = BoardArt.frame
        scale = min(size.width / f.width, size.height / f.height)
        offset = CGPoint(x: (size.width - f.width * scale) / 2 - f.minX * scale,
                         y: (size.height - f.height * scale) / 2 - f.minY * scale)
    }

    func point(_ p: [Double]) -> CGPoint {
        CGPoint(x: offset.x + CGFloat(p[0]) * scale, y: offset.y + CGFloat(p[1]) * scale)
    }

    func path(_ polygon: [[Double]]) -> Path {
        var path = Path()
        path.addLines(polygon.map(point))
        path.closeSubpath()
        return path
    }
}

/// Colors for civilizations. Rebel factions take a lighter shade of the realm they split from.
enum Palette {
    static let base: [CivilizationID: Color] = [
        "greece": Color(red: 0.20, green: 0.42, blue: 0.85),
        "egypt": Color(red: 0.85, green: 0.65, blue: 0.13),
        "italia": Color(red: 0.80, green: 0.20, blue: 0.20),
        "mesopotamia": Color(red: 0.18, green: 0.62, blue: 0.35),
    ]

    static func color(_ civ: CivilizationID?, _ state: GameState) -> Color {
        guard let civ else { return Color(white: 0.92) }
        if civ == nativesID { return Color(white: 0.72) }
        if civ == barbariansID { return Color(red: 0.45, green: 0.30, blue: 0.20) }
        if let parent = state.civs[civ]?.rebelledFrom {
            return color(parent, state).opacity(0.45)
        }
        return base[civ] ?? .purple
    }

    static func name(_ civ: CivilizationID, _ state: GameState) -> String {
        if let display = state.civs[civ]?.displayName { return display }
        if civ == nativesID { return "Natives" }
        if civ == barbariansID { return "Barbarians" }
        return civ.prefix(1).uppercased() + civ.dropFirst()
    }
}
